'        || apex_javascript.add_attribute(p_name => ''suffix'',   p_value => p_dynamic_action.attribute_08, p_omit_null => false, p_add_comma => false)',
'        || ''}); }'';',
'',
'    return l_result;',
'end render_amount_in_words;'))
